#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=7

banner "UANL Repo Search — Deploy to Cloudflare Workers, decommission Vercel"

# ── Stage 1: Cloudflare login ─────────────────────────────────────────────
stage "Cloudflare: login"
say "You need a Cloudflare account (free tier is fine) with Workers enabled."
step "Logging in via wrangler (browser will open)…"
pnpm exec wrangler login
pnpm exec wrangler whoami
pause "Logged in to the correct account?"
# ──────────────────────────────────────────────────────────────────────────

# ── Stage 2: secret verification ──────────────────────────────────────────
stage "Cloudflare: verify GITHUB_TOKEN secret"
say "The Worker needs its GITHUB_TOKEN secret binding before deploy."
step "Checking existing secrets…"
if pnpm exec wrangler secret list 2>/dev/null | grep -q GITHUB_TOKEN; then
  note "GITHUB_TOKEN secret already set."
else
  warn "GITHUB_TOKEN secret is NOT set."
  note "Run ./scripts/setup-github-token.sh first, or set it directly:"
  note "  printf '%s' \"\$GITHUB_TOKEN\" | pnpm exec wrangler secret put GITHUB_TOKEN"
  confirm "Continue without the secret? (/api/stats will 500 in production)" || exit 1
fi
# ──────────────────────────────────────────────────────────────────────────

# ── Stage 3: KV namespace ─────────────────────────────────────────────────
stage "Cloudflare: STATS_KV namespace"
say "/api/stats caches its payload in KV (24h TTL) between the edge cache and"
say "GitHub. The namespace must exist before deploy."
if grep -q '"id": "00000000000000000000000000000000"' wrangler.jsonc; then
  step "Creating the production namespace…"
  KV_OUT=$(pnpm exec wrangler kv namespace create STATS_KV 2>&1)
  printf '%s\n' "$KV_OUT"
  KV_ID=$(printf '%s' "$KV_OUT" | sed -n 's/.*"id": *"\([a-f0-9]\{32\}\)".*/\1/p' | head -n1)
  step "Creating the preview namespace (used by wrangler dev)…"
  KV_PREVIEW_OUT=$(pnpm exec wrangler kv namespace create STATS_KV --preview 2>&1)
  printf '%s\n' "$KV_PREVIEW_OUT"
  KV_PREVIEW_ID=$(printf '%s' "$KV_PREVIEW_OUT" | sed -n 's/.*"preview_id": *"\([a-f0-9]\{32\}\)".*/\1/p' | head -n1)
  if [[ -n "$KV_ID" && -n "$KV_PREVIEW_ID" ]]; then
    sed -i "s/\"id\": \"00000000000000000000000000000000\"/\"id\": \"$KV_ID\"/" wrangler.jsonc
    sed -i "s/\"preview_id\": \"00000000000000000000000000000000\"/\"preview_id\": \"$KV_PREVIEW_ID\"/" wrangler.jsonc
    printf '  %s✓ wrote%s namespace IDs → wrangler.jsonc (commit this change)\n' "$GREEN" "$RESET"
  else
    warn "couldn't parse namespace IDs from the output above; fill wrangler.jsonc by hand"
    SKIPPED+=("KV namespace IDs into wrangler.jsonc")
  fi
else
  note "wrangler.jsonc already has real namespace IDs."
fi
# ──────────────────────────────────────────────────────────────────────────

# ── Stage 4: GitHub integration for PR previews ───────────────────────────
stage "Cloudflare: Workers Builds (GitHub previews)"
say "Connecting the GitHub repo gives every branch/PR a preview deployment"
say "automatically. One-time dashboard step."
if confirm "Connect the repo to Workers Builds for PR previews?"; then
  open_url "https://dash.cloudflare.com/?to=/:account/workers-and-pages/create"
  step "Workers & Pages → Import a repository → pick iksaku/uanl-repo-search."
  step "Build command: pnpm build · Deploy command: pnpm exec wrangler deploy"
  step "  (or let it reuse wrangler.jsonc; no framework preset needed)."
  step "Under Variables/Secrets for BOTH production and preview, add GITHUB_TOKEN."
  pause "Repo connected and first build started?"
else
  note "Skipped. Deploys stay manual via wrangler deploy."
fi
# ──────────────────────────────────────────────────────────────────────────

# ── Stage 5: build + deploy ───────────────────────────────────────────────
stage "Cloudflare: build and deploy"
step "Building the Worker + static assets…"
pnpm build
step "Deploying…"
DEPLOY_OUTPUT=$(pnpm exec wrangler deploy 2>&1)
printf '%s\n' "$DEPLOY_OUTPUT"
DEPLOY_URL=$(printf '%s' "$DEPLOY_OUTPUT" | sed -n 's/.*\(https:\/\/[^ ]*\.workers\.dev\).*/\1/p' | head -n1 || true)
if [[ -z "$DEPLOY_URL" ]]; then
  ask DEPLOY_URL "Paste the deployed workers.dev URL (from the output above):"
fi
# ──────────────────────────────────────────────────────────────────────────

# ── Stage 6: production smoke test ────────────────────────────────────────
stage "Cloudflare: production smoke test"
say "Verifying the deployed site."
step "GET $DEPLOY_URL/ → expect 200"
curl -s -o /dev/null -w "  / → %{http_code}\n" "$DEPLOY_URL/"
step "GET $DEPLOY_URL/api/stats → expect 200 with real counts"
FIRST_DATE=$(curl -s -D - -o /tmp/uanl-stats-first.json "$DEPLOY_URL/api/stats" | sed -n 's/^[Dd]ate: //p' | tr -d '\r')
cat /tmp/uanl-stats-first.json
printf '\n'
step "Repeat /api/stats — same Date header means it was served from the edge cache"
SECOND_DATE=$(curl -s -D - -o /dev/null "$DEPLOY_URL/api/stats" | sed -n 's/^[Dd]ate: //p' | tr -d '\r')
if [[ -n "$FIRST_DATE" && "$FIRST_DATE" == "$SECOND_DATE" ]]; then
  note "✓ edge cache hit (identical Date: $FIRST_DATE)"
else
  warn "Date headers differ ('$FIRST_DATE' vs '$SECOND_DATE') — repeat hit GitHub; check the cache logic"
fi
open_url "$DEPLOY_URL/"
pause "Site loads and hydrates, with zero console errors in devtools?"
# ──────────────────────────────────────────────────────────────────────────

# ── Stage 7: cutover decision + Vercel decommission ───────────────────────
stage "Cutover and Vercel decommission"
say "Decide how the site is reached, then retire Vercel."
step "Option A (default): keep the workers.dev URL — nothing more to do."
step "Option B: custom domain → Cloudflare dashboard → Workers & Pages →"
step "  uanl-repo-search → Settings → Domains & Routes → Add. If the domain's"
step "  DNS lives on Cloudflare, this is automatic; otherwise point DNS."
if confirm "Use a custom domain?"; then
  open_url "https://dash.cloudflare.com/?to=/:account/workers/services/view/uanl-repo-search/production/settings/domains"
  pause "Domain/route added and serving?"
fi
warn "Irreversible-ish step next: decommissioning Vercel."
step "Vercel dashboard → uanl-repo-search project → Settings → Delete Project"
step "  (or 'Disable' first if you want a rollback window)."
if confirm "Decommission the Vercel project now?"; then
  open_url "https://vercel.com/dashboard"
  pause "Vercel project deleted/disabled?"
else
  note "Skipped. The repo no longer references Vercel; delete it when ready."
fi
# ──────────────────────────────────────────────────────────────────────────

finish
